import { normalizeEntry, buildCards, aggregate, localDate, exampleEntries, validateBackup } from './core.js';

const $ = s => document.querySelector(s);
const esc = v => String(v ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const dateText = date => new Date(date+'T12:00:00').toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'});
const defaults = () => ({version:1,entries:[],attempts:[]});
let state=defaults(), db, route='today', editing=null, drinkFilter='', activeDrink=null;
let practiceMode='recall', deck=[], cardIndex=0, answerShown=false, cardRated=false;
let worker, modelReady=false, modelLoading=false, pendingAI=null, aiBusy=false, lastAI='';
let deleteId=null, toastTimer, aiPromiseId=0, organizedSteps='';

function notify(message){$('#toast').textContent=message;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,4500)}
async function openDatabase(){
  db=await new Promise((resolve,reject)=>{const r=indexedDB.open('barista-buddy',1);r.onupgradeneeded=()=>r.result.createObjectStore('notebook');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);r.onblocked=()=>reject(Error('Close other Barista Buddy tabs and reload.'))});
  const stored=await new Promise((resolve,reject)=>{const r=db.transaction('notebook').objectStore('notebook').get('state');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});
  if(stored)state=validateBackup(stored);
}
async function commit(next){
  if(!db)throw Error('Notebook storage is unavailable. Enable browser storage and reload before saving.');
  await new Promise((resolve,reject)=>{const tx=db.transaction('notebook','readwrite');tx.objectStore('notebook').put(next,'state');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||Error('Unable to save.'))});
  state=next;$('#demo-banner').hidden=!state.entries.some(x=>x.demo);return next;
}
function fail(error){notify(error.message||'Something went wrong. Your input is still here.');console.error(error)}
function heading(kicker,title,description,action=''){return `<div class="page-heading"><div><p class="eyebrow">${kicker}</p><h1>${title}</h1><p class="sub">${description}</p></div>${action}</div>`}
function entrySummary(entry){return `<div class="entry"><div class="entry-icon" aria-hidden="true">☕</div><div class="entry-text"><h3>${esc(entry.drink)}</h3><small>${dateText(entry.date)} · ${entry.count} made${entry.demo?' · Sample':''}</small><p>${esc(entry.struggle||entry.notes||'A new drink in your notebook.')}</p></div><button class="text-button" data-edit="${esc(entry.id)}">Edit</button></div>`}
function render(){
  route=['today','notebook','practice','progress'].includes(location.hash.slice(1))?location.hash.slice(1):'today';
  document.querySelectorAll('[data-route]').forEach(a=>{a.classList.toggle('active',a.dataset.route===route);a.toggleAttribute('aria-current',a.dataset.route===route);if(a.dataset.route===route)a.setAttribute('aria-current','page')});
  $('#demo-banner').hidden=!state.entries.some(x=>x.demo);
  $('#view').innerHTML=({today:todayView,notebook:notebookView,practice:practiceView,progress:progressView}[route])();
  wireView();
}
function todayView(){
  const stats=aggregate(state.entries,state.attempts), e=editing?state.entries.find(x=>x.id===editing):null;
  return heading('YOUR SHIFT JOURNAL',editing?'Let’s update that entry.':'What did you make today?','A few notes now. A little more confidence next shift.')+`<div class="layout"><div><div class="card">
    <div class="card-heading"><div><h2><span class="section-number">01</span>${editing?'Edit drink entry':'Log a drink'}</h2><p class="sub">Write it the way your café taught you.</p></div><span class="small-label">${editing?'Saved recipe & notes':'One drink per entry'}</span></div>
    <form id="shift-form"><div class="quick-picks" aria-label="Quick drink names">${['Latte','Cappuccino','Americano','Flat white','Mocha'].map(d=>`<button type="button" class="chip ${e?.drink===d?'selected':''}" data-pick="${d}">${d}</button>`).join('')}</div>
    <div class="field-grid"><div class="field"><label for="drink">Drink name</label><input id="drink" name="drink" required maxlength="80" placeholder="e.g. Iced oat latte" value="${esc(e?.drink)}"></div><div class="field"><label for="date">Shift date</label><input id="date" name="date" type="date" required value="${e?.date||localDate()}"></div></div>
    <div class="field-grid"><div class="field"><label for="count">How many did you make?</label><input id="count" name="count" type="number" min="1" max="999" required value="${e?.count||1}"></div><div class="field"><label for="size">Cup size <span class="optional">optional</span></label><input id="size" name="size" maxlength="60" placeholder="e.g. 12 oz / medium" value="${esc(e?.size)}"></div></div>
    <div class="field-grid"><div class="field"><label for="shots">Espresso shots <span class="optional">optional</span></label><input id="shots" name="shots" type="number" min="0" max="12" value="${e?.shots??''}" placeholder="2"></div><div class="field"><label for="milk">Milk <span class="optional">optional</span></label><input id="milk" name="milk" maxlength="60" value="${esc(e?.milk)}" placeholder="e.g. Whole milk or oat"></div></div>
    <div class="field"><label for="steps">Steps I learned <span class="optional">one step per line</span></label><textarea id="steps" name="steps" maxlength="6000" placeholder="1. Dose and tamp the coffee.&#10;2. Pull the espresso shots.&#10;3. Follow the café’s milk and pouring routine.">${esc(e?.steps?.join('\n'))}</textarea></div>
    <div class="button-row" style="margin-bottom:18px"><button type="button" class="secondary" id="organize-notes">Organize my steps with AI</button><span class="fine" style="margin:0">Review before applying.</span></div><div id="organize-output" class="ai-output" hidden></div><button type="button" id="apply-organized" class="secondary" style="margin:12px 0 20px" hidden>Use these steps</button>
    <div class="field"><label for="struggle">What felt tricky? <span class="optional">optional</span></label><input id="struggle" name="struggle" maxlength="500" placeholder="e.g. Milk texture, remembering the order" value="${esc(e?.struggle)}"></div>
    <div class="field"><label for="trainer">Trainer’s advice <span class="optional">optional</span></label><textarea id="trainer" name="trainer" maxlength="3000" style="min-height:78px" placeholder="What helped, or what to try next time…">${esc(e?.trainer)}</textarea></div>
    <div class="field"><label for="vocab">A phrase I learned <span class="optional">optional</span></label><input id="vocab" name="vocab" maxlength="500" placeholder='e.g. “Extra shot” means one more espresso shot.' value="${esc(e?.vocab)}"></div>
    <div class="field"><label for="notes">Other notes <span class="optional">optional</span></label><textarea id="notes" name="notes" maxlength="3000" style="min-height:78px" placeholder="Anything else you want to remember…">${esc(e?.notes)}</textarea></div>
    <div class="field"><label for="confidence">How confident did you feel? <span class="inline-score" id="confidence-label">${e?.confidence||3}/5</span></label><input id="confidence" name="confidence" type="range" min="1" max="5" step="1" value="${e?.confidence||3}"><div class="range-labels"><span>Still learning</span><span>Feeling good</span></div></div>
    <div class="form-footer"><p class="fine">Your notebook follows your café’s recipes.</p><div class="button-row">${editing?'<button type="button" class="secondary" id="cancel-edit">Cancel</button>':''}<button class="primary" type="submit">${editing?'Save changes':'Save drink'}</button></div></div></form></div></div>
    <aside><div class="card dark-card"><p class="eyebrow">A MOMENT TO PRACTICE</p><h2>A small review.<br>A smoother next shift.</h2><p>Turn the drinks you’ve learned into a few quick recall cards.</p><button class="primary" id="go-practice">Practice my drinks</button><p class="fine">Based on your saved steps and notes.</p></div>
    <div class="card"><h2>Your notebook so far</h2><div class="metric-row"><div class="metric"><strong>${stats.shifts}</strong><span>shifts logged</span></div><div class="metric"><strong>${stats.drinks}</strong><span>drinks learned</span></div><div class="metric"><strong>${stats.total}</strong><span>drinks made</span></div></div>${state.entries.some(x=>x.demo)?'<p class="fine">Includes labeled sample entries.</p>':''}</div>
    <div class="card"><div class="card-heading"><h2>Recent entries</h2><a class="text-button" href="#notebook">See all</a></div>${state.entries.length?[...state.entries].sort((a,b)=>b.date.localeCompare(a.date)||b.createdAt.localeCompare(a.createdAt)).slice(0,3).map(entrySummary).join(''):`<div class="empty"><h3>Your first shift starts here.</h3><p>Save a drink, or explore with a sample notebook.</p><button class="secondary" id="sample-inline">Try sample notebook</button></div>`}</div></aside></div>`;
}
function grouped(){return [...new Set(state.entries.map(x=>x.drink))].map(name=>({name,entries:state.entries.filter(x=>x.drink===name).sort((a,b)=>b.date.localeCompare(a.date)||b.createdAt.localeCompare(a.createdAt))})).sort((a,b)=>a.name.localeCompare(b.name))}
function notebookView(){
  if(activeDrink){const group=grouped().find(x=>x.name===activeDrink);if(group)return detailView(group);activeDrink=null}
  const drinks=grouped().filter(x=>x.name.toLowerCase().includes(drinkFilter.toLowerCase()));
  return heading('YOUR PERSONAL HANDBOOK','Drink notebook','Your recipes. Your trainer’s tips. All in one place.','<button class="primary" id="new-entry">Log a drink</button>')+`<div class="search-bar"><label for="drink-search" class="visually-hidden">Search your drinks</label><input id="drink-search" type="search" placeholder="Find a drink…" value="${esc(drinkFilter)}"></div><div class="grid-three" id="drink-grid">${drinks.length?drinks.map(g=>`<button class="drink-card" data-drink="${esc(g.name)}"><span class="drink-count">${g.entries.length} ${g.entries.length===1?'entry':'entries'} · ${g.entries.reduce((s,x)=>s+x.count,0)} made</span><h2>${esc(g.name)}</h2><p>${esc(g.entries[0].size||'Your café recipe')} ${g.entries[0].milk?'· '+esc(g.entries[0].milk):''}</p><span class="tag">${g.entries[0].steps.length?g.entries[0].steps.length+' saved steps':'Add your steps'}${g.entries.every(x=>x.demo)?' · Sample':''}</span></button>`).join(''):`<div class="card empty"><h3>${drinkFilter?'No drinks match that search.':'A handbook built by you.'}</h3><p>${drinkFilter?'Try a different drink name.':'Start with a drink you learned on your last shift.'}</p><button class="primary" id="empty-log">Log a drink</button></div>`}</div>`;
}
function detailView(group){
  const e=group.entries[0];
  return `<button class="text-button" id="back-notebook">All drinks</button>`+heading('DRINK NOTES',esc(group.name),`${group.entries.reduce((s,x)=>s+x.count,0)} made across ${new Set(group.entries.map(x=>x.date)).size} shift dates.`,`<button class="primary" data-edit="${esc(e.id)}">Edit latest entry</button>`)+`<div class="layout"><div class="card"><div class="row-between"><h2>Latest recipe notes</h2><span class="small-label">${dateText(e.date)}${e.demo?' · Sample':''}</span></div><div class="recipe-facts"><div><small>Cup size</small>${esc(e.size||'Not recorded')}</div><div><small>Espresso shots</small>${e.shots??'Not recorded'}</div><div><small>Milk</small>${esc(e.milk||'Not recorded')}</div></div>${e.steps.length?`<ol class="steps">${e.steps.map(s=>`<li>${esc(s)}</li>`).join('')}</ol>`:'<p class="empty">No steps yet. Add the routine your trainer taught you.</p>'}<p class="fine">These are your recorded notes, not a universal drink recipe.</p>${e.struggle?`<div class="divider"></div><h3>What felt tricky</h3><p class="prewrap">${esc(e.struggle)}</p>`:''}${e.trainer?`<h3>Trainer’s advice</h3><p class="prewrap">${esc(e.trainer)}</p>`:''}${e.vocab?`<h3>A phrase I learned</h3><p class="prewrap">${esc(e.vocab)}</p>`:''}${e.notes?`<h3>Other notes</h3><p class="prewrap">${esc(e.notes)}</p>`:''}<div class="divider"></div><button class="secondary" id="practice-drink">Practice this drink</button></div><aside><div class="card"><h2>Shift history</h2>${group.entries.map(x=>`<div class="entry"><div class="entry-text"><p class="history-date">${dateText(x.date)}${x.demo?' · Sample':''}</p><h3>${x.count} made · Confidence ${x.confidence}/5</h3><p>${esc(x.struggle||x.notes||'Practice logged.')}</p><div class="button-row"><button class="text-button" data-edit="${esc(x.id)}">Edit</button><button class="text-button" data-delete="${esc(x.id)}">Delete</button></div></div></div>`).join('')}</div></aside></div>`;
}
function practiceView(){
  return heading('A LITTLE PRACTICE','Ready for your next shift?','Review your notes at your own pace. It’s okay to check the answer.')+`<div class="mode-tabs" aria-label="Practice modes">${[['recall','Drink recall'],['phrases','Workplace phrases'],['coach','AI coach']].map(([id,title])=>`<button class="${practiceMode===id?'active':''}" data-mode="${id}" aria-pressed="${practiceMode===id}">${title}</button>`).join('')}</div>`+(practiceMode==='coach'?coachView():recallView());
}
function recallView(){
  if(!deck.length)return `<div class="card empty"><h2>${practiceMode==='phrases'?'Collect a phrase, then practice it.':'Your own notes make the best practice.'}</h2><p>${practiceMode==='phrases'?'Add a workplace phrase and its meaning when you log a drink.':'Save a drink with steps, shot count, milk, or trainer advice to create recall cards.'}</p><div class="button-row"><button class="primary" id="empty-log">Log a drink</button><button class="secondary" id="sample-inline">Try sample notebook</button></div></div>`;
  if(cardIndex>=deck.length)return `<div class="card practice-card"><p class="eyebrow">PRACTICE COMPLETE</p><h2>A little more ready<br>than you were before.</h2><p class="sub">You reviewed ${deck.length} ${deck.length===1?'card':'cards'}. Come back whenever you need a refresher.</p><div class="button-row"><button class="primary" id="restart-practice">Practice again</button><a class="button secondary" href="#progress">View my progress</a></div></div>`;
  const c=deck[cardIndex];
  return `<div class="layout"><div class="card practice-card"><p class="eyebrow">${esc(c.drink)}${c.demo?' · SAMPLE':''} · CARD ${cardIndex+1} OF ${deck.length}</p><h2>${esc(c.question)}</h2><p class="sub">Say it out loud, or think it through.</p>${answerShown?`<div class="answer"><h3>Your saved notes</h3><p class="prewrap">${esc(c.answer)}</p><span class="fine">From ${dateText(c.date)}. Check your trainer if anything has changed.</span></div><p class="fine">How did that feel?</p><div class="button-row"><button class="secondary" data-rate="again" ${cardRated?'disabled':''}>Review again</button><button class="primary" data-rate="got-it" ${cardRated?'disabled':''}>Got it</button></div>`:`<button class="primary" id="show-answer">Show my notes</button>`}<div class="progress-bar"><span style="width:${Math.round(cardIndex/deck.length*100)}%"></span></div><p class="fine">Recall practice · Your self-rating is saved, not AI-graded.</p></div><aside><div class="card dark-card"><p class="eyebrow">NO PRESSURE</p><h2>Remember the routine,<br>one step at a time.</h2><p>These cards use what you actually wrote down. There’s no need to learn someone else’s recipe.</p></div><div class="card"><h2>Today’s practice</h2><p class="sub">${deck.length} cards from your notebook.</p><button class="text-button" id="restart-practice">Restart this set</button></div></aside></div>`;
}
function coachView(){return `<div class="layout"><div class="card"><div class="card-heading"><div><h2>A coach for your own notes</h2><p class="sub">Ask about a drink, or reflect on what felt tricky.</p></div><span class="tag" id="coach-state">${modelReady?'AI ready on this device':'Local AI'}</span></div><div class="notice">Suggestions may be wrong. Compare them with your saved notes and your trainer’s instructions.</div><form id="coach-form"><div class="field"><label for="coach-drink">Use notes about</label><select id="coach-drink" name="drink"><option value="">My latest shift notes</option>${grouped().map(g=>`<option value="${esc(g.name)}">${esc(g.name)}</option>`).join('')}</select></div><div class="field"><label for="coach-question">What would you like to review?</label><textarea id="coach-question" required maxlength="600" placeholder="What should I focus on before my next shift?">What should I focus on before my next shift?</textarea></div><div class="button-row"><button class="primary" type="submit" id="ask-coach" ${aiBusy?'disabled':''}>${aiBusy?'Thinking on your device…':'Ask my coach'}</button><button class="secondary" type="button" id="coach-setup">${modelReady?'AI settings':'Prepare AI coach'}</button></div><p class="fine">Uses up to three recent entries. No notes are uploaded for inference.</p></form><div id="coach-output" class="ai-output" role="status" ${lastAI?'':'hidden'}>${esc(lastAI)}</div></div><aside><div class="card dark-card"><p class="eyebrow">OPEN & ON YOUR DEVICE</p><h2>Your learning<br>stays yours.</h2><p>SmolLM2 runs inside your browser. No API key, subscription, or remote model chat is needed.</p><p class="fine">The first model download needs internet. Small local models have limits.</p></div><div class="card"><h2>Try asking</h2><p class="sub">“Summarize my trainer’s advice.”</p><p class="sub">“Ask me one question about the steps I recorded.”</p><p class="sub">“Explain this customer phrase in simple English.”</p></div></aside></div>`}
function progressView(){
  const s=aggregate(state.entries,state.attempts), all=grouped();const days=Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-6+i);const key=localDate(d);return {label:d.toLocaleDateString(undefined,{weekday:'short'}),n:state.entries.filter(e=>e.date===key).reduce((sum,e)=>sum+e.count,0)}});const max=Math.max(1,...days.map(x=>x.n));
  return heading('YOUR LEARNING JOURNEY','Small shifts. Real progress.','A look at what you’ve practiced and what you want to revisit.')+`<div class="stats-grid"><div class="stat-card"><strong>${s.shifts}</strong><span>shift dates logged</span></div><div class="stat-card"><strong>${s.total}</strong><span>drinks made</span></div><div class="stat-card"><strong>${s.attempts}</strong><span>recall cards reviewed</span></div></div><div class="layout"><div><div class="card"><h2>Drinks made in the last 7 days</h2><div class="activity-bars" role="img" aria-label="${days.map(x=>`${x.label}: ${x.n} drinks`).join(', ')}">${days.map(x=>`<div class="activity-column"><strong>${x.n}</strong><div class="bar" style="height:${Math.max(3,x.n/max*105)}px"></div><span>${x.label}</span></div>`).join('')}</div></div><div class="card"><h2>Confidence by drink</h2><p class="sub">Your latest self-rating, out of 5.</p>${all.length?all.map(g=>`<div class="entry"><div class="entry-text"><div class="row-between"><h3>${esc(g.name)}${g.entries.every(x=>x.demo)?' <span class="tag">Sample</span>':''}</h3><span class="inline-score">${g.entries[0].confidence}/5</span></div><div class="progress-bar"><span style="width:${g.entries[0].confidence*20}%"></span></div><p>${g.entries.reduce((sum,e)=>sum+e.count,0)} made · ${g.entries.length} entries</p></div></div>`).join(''):'<p class="empty">Your confidence ratings will appear after you log a drink.</p>'}</div></div><aside><div class="card"><h2>Things to revisit</h2><p class="sub">What you said felt tricky, grouped by drink.</p>${all.filter(g=>g.entries.some(e=>e.struggle)).map(g=>`<div class="entry"><div class="entry-text"><h3>${esc(g.name)}</h3>${[...new Set(g.entries.map(e=>e.struggle).filter(Boolean))].slice(0,3).map(t=>`<p>${esc(t)}</p>`).join('')}<small>${g.entries.filter(e=>e.struggle).length} entries with practice notes</small></div></div>`).join('')||'<p class="empty">Add what felt tricky to a shift log to keep track here.</p>'}</div><div class="card"><h2>Recall practice</h2><div class="metric-row"><div class="metric"><strong>${s.gotIt}</strong><span>marked “got it”</span></div><div class="metric"><strong>${s.again}</strong><span>marked for review</span></div></div><p class="fine">These are your self-ratings, not a skill assessment.</p><div class="divider"></div><a class="button secondary" href="#practice">Review my drinks</a></div></aside></div>`;
}
function startDeck(filter=null){deck=buildCards(state.entries,state.attempts,practiceMode,filter);cardIndex=0;answerShown=false;cardRated=false}
function goLog(){editing=null;activeDrink=null;location.hash='today';render();$('#drink')?.focus()}
function wireView(){
  $('#shift-form')?.addEventListener('submit',saveEntry);
  $('#organize-notes')?.addEventListener('click',organizeNotes);
  $('#apply-organized')?.addEventListener('click',()=>{if(organizedSteps){$('#steps').value=organizedSteps;$('#apply-organized').hidden=true;notify('Steps added to your draft. Review them before saving.')}});
  document.querySelectorAll('[data-pick]').forEach(b=>b.onclick=()=>{$('#drink').value=b.dataset.pick;document.querySelectorAll('[data-pick]').forEach(c=>c.classList.toggle('selected',c===b));$('#drink').focus()});
  $('#confidence')?.addEventListener('input',e=>$('#confidence-label').textContent=e.target.value+'/5');
  document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>{editing=b.dataset.edit;location.hash='today';render();$('#drink').focus()});
  document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>{deleteId=b.dataset.delete;$('#delete-dialog').showModal()});
  document.querySelectorAll('[data-drink]').forEach(b=>b.onclick=()=>{activeDrink=b.dataset.drink;render();window.scrollTo(0,0)});
  for(const id of ['new-entry','empty-log'])if($('#'+id))$('#'+id).onclick=goLog;
  for(const id of ['sample-inline'])if($('#'+id))$('#'+id).onclick=()=>loadDemo().catch(fail);
  $('#cancel-edit')?.addEventListener('click',()=>{editing=null;render()});
  $('#back-notebook')?.addEventListener('click',()=>{activeDrink=null;render()});
  $('#drink-search')?.addEventListener('input',e=>{drinkFilter=e.target.value;const selection=e.target.selectionStart;render();$('#drink-search').focus();if($('#drink-search').type!=='search')$('#drink-search').setSelectionRange(selection,selection)});
  $('#go-practice')?.addEventListener('click',()=>{practiceMode='recall';startDeck();location.hash='practice';render()});
  $('#practice-drink')?.addEventListener('click',()=>{practiceMode='recall';startDeck(activeDrink);location.hash='practice';render()});
  document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{practiceMode=b.dataset.mode;startDeck();render()});
  $('#show-answer')?.addEventListener('click',()=>{answerShown=true;render()});
  document.querySelectorAll('[data-rate]').forEach(b=>b.onclick=()=>rateCard(b.dataset.rate));
  $('#restart-practice')?.addEventListener('click',()=>{startDeck();render()});
  $('#coach-setup')?.addEventListener('click',()=>$('#settings-dialog').showModal());
  $('#coach-form')?.addEventListener('submit',askCoach);
}
async function organizeNotes(){
  if(aiBusy){notify('The coach is already thinking. Please wait.');return}
  if(!modelReady){$('#settings-dialog').showModal();$('#model-status').textContent='Prepare the coach first, then return to your draft.';return}
  const steps=$('#steps').value.trim();
  if(!steps){notify('Write the steps you remember first. AI can help tidy them up.');$('#steps').focus();return}
  aiBusy=true;const button=$('#organize-notes');button.disabled=true;button.textContent='Organizing on your device…';const output=$('#organize-output');output.hidden=false;output.textContent='Reading your steps locally…';$('#apply-organized').hidden=true;
  try{const result=await new Promise((resolve,reject)=>{const id=++aiPromiseId;pendingAI={id,resolve,reject};worker.postMessage({type:'generate',id,question:'Rewrite ONLY the saved steps as a short numbered list. Keep the same order and details. Add nothing. Do not give advice.',entries:[{drink:$('#drink').value,steps:steps.split('\n')}]})});
    organizedSteps=result;output.textContent=result+'\n\nAI draft · Compare each step with what your trainer taught you.';$('#apply-organized').hidden=false;
  }catch(error){output.textContent='Could not organize your steps. Your original draft is still here. '+error.message;fail(error)}finally{aiBusy=false;button.disabled=false;button.textContent='Organize my steps with AI'}
}
async function saveEntry(event){event.preventDefault();const form=event.target,button=form.querySelector('[type=submit]');button.disabled=true;try{const data=Object.fromEntries(new FormData(form));const old=editing?state.entries.find(x=>x.id===editing):null;const entry=normalizeEntry({...data,id:old?.id||crypto.randomUUID(),createdAt:old?.createdAt||new Date().toISOString(),demo:old?.demo||false});await commit({...state,entries:[...state.entries.filter(x=>x.id!==entry.id),entry]});editing=null;deck=[];render();notify('Drink saved. Your notebook is growing.')}catch(error){fail(error);button.disabled=false}}
async function rateCard(rating){if(cardRated)return;cardRated=true;const c=deck[cardIndex];try{await commit({...state,attempts:[...state.attempts,{id:crypto.randomUUID(),cardId:c.id,entryId:c.entryId,rating,date:new Date().toISOString(),demo:c.demo}].slice(-10000)});cardIndex++;answerShown=false;cardRated=false;render()}catch(error){cardRated=false;fail(error)}}
async function loadDemo(){const existing=state.entries.filter(x=>!x.demo);await commit({...state,entries:[...existing,...exampleEntries()],attempts:state.attempts.filter(x=>!x.demo)});editing=null;activeDrink=null;startDeck();render();notify('Sample notebook loaded. Example entries are labeled.')}
async function clearDemo(){await commit({...state,entries:state.entries.filter(x=>!x.demo),attempts:state.attempts.filter(x=>!x.demo)});editing=null;activeDrink=null;startDeck();render();notify('Sample entries removed. Your own notes are kept.')}
function ensureWorker(){if(worker)return;worker=new Worker('ai-worker.js',{type:'module'});worker.onmessage=event=>{const m=event.data;if(m.type==='progress'){if(!modelLoading)return;$('#model-status').textContent=m.message;if(m.progress!=null){$('#model-progress').hidden=false;$('#model-progress').value=m.progress}}if(m.type==='ready'){modelReady=true;modelLoading=false;$('#load-model').disabled=false;$('#load-model').textContent='AI coach ready';$('#cancel-model').hidden=true;$('#model-progress').hidden=true;$('#model-status').textContent='SmolLM2 is ready. Inference runs on this device.';notify('Your on-device coach is ready.')}if(m.type==='result'&&pendingAI?.id===m.id){pendingAI.resolve(m.text);pendingAI=null}if(m.type==='error'){if(modelLoading){modelLoading=false;modelReady=false;$('#load-model').disabled=false;$('#load-model').textContent='Retry AI download';$('#cancel-model').hidden=true;$('#model-progress').hidden=true;$('#model-status').textContent=m.message;}if(pendingAI){pendingAI.reject(Error(m.message));pendingAI=null}notify(m.message)}};worker.onerror=()=>{modelLoading=false;modelReady=false;$('#load-model').disabled=false;$('#cancel-model').hidden=true;$('#model-status').textContent='The AI engine could not start. Try a recent desktop Chrome or Edge browser.';pendingAI?.reject(Error('AI engine unavailable.'));pendingAI=null;worker?.terminate();worker=null}}
function loadModel(){if(modelReady||modelLoading)return;ensureWorker();modelLoading=true;$('#load-model').disabled=true;$('#cancel-model').hidden=false;$('#model-status').textContent='Downloading the open model. Keep this tab open…';worker.postMessage({type:'load'})}
function cancelModel(){worker?.terminate();worker=null;modelLoading=false;modelReady=false;$('#load-model').disabled=false;$('#load-model').textContent='Prepare AI coach';$('#cancel-model').hidden=true;$('#model-progress').hidden=true;$('#model-status').textContent='Download canceled. Completed files may remain cached.';pendingAI?.reject(Error('AI canceled.'));pendingAI=null}
async function askCoach(event){event.preventDefault();if(aiBusy)return;if(!modelReady){$('#settings-dialog').showModal();$('#model-status').textContent='Prepare the coach here first, then return to your question.';return}const selected=$('#coach-drink').value,question=$('#coach-question').value;const entries=[...state.entries].filter(x=>!selected||x.drink===selected).sort((a,b)=>b.date.localeCompare(a.date)).slice(0,3);if(!entries.length){notify('Log a drink first so your coach can use your own notes.');return}aiBusy=true;const button=$('#ask-coach');button.disabled=true;button.textContent='Thinking on your device…';const output=$('#coach-output');output.hidden=false;output.textContent='Reading your saved notes locally…';try{ensureWorker();const text=await new Promise((resolve,reject)=>{const id=++aiPromiseId;pendingAI={id,resolve,reject};worker.postMessage({type:'generate',id,question,entries:entries.map(({drink,steps,shots,milk,struggle,trainer,vocab,notes})=>({drink,steps,shots,milk,struggle,trainer,vocab,notes}))})});lastAI=text+'\n\nAI suggestion · Check this with your trainer. Your notebook has not been changed.';if($('#coach-output')){$('#coach-output').textContent=text+'\n\nAI suggestion · Check this with your trainer. Your notebook has not been changed.';$('#coach-output').hidden=false}}catch(error){if($('#coach-output'))$('#coach-output').textContent='The coach could not finish. Your saved notebook is unaffected. '+error.message;fail(error)}finally{aiBusy=false;if($('#ask-coach')){$('#ask-coach').disabled=false;$('#ask-coach').textContent='Ask my coach'}}}
function download(content,name,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
$('#export').onclick=()=>{download(JSON.stringify(state,null,2),'barista-buddy-backup-'+localDate()+'.json','application/json');notify('Backup exported.')};
$('#import-file').onchange=async event=>{const file=event.target.files[0];if(!file)return;try{if(file.size>10000000)throw Error('Choose a notebook backup smaller than 10 MB.');const data=validateBackup(JSON.parse(await file.text()));const ids=new Set(state.entries.map(x=>x.id)),attemptIds=new Set(state.attempts.map(x=>x.id));await commit({...state,entries:[...state.entries,...data.entries.filter(x=>!ids.has(x.id))],attempts:[...state.attempts,...data.attempts.filter(x=>!attemptIds.has(x.id))]});startDeck();render();notify('Backup imported. Existing notes were kept.')}catch(error){fail(error)}event.target.value=''};
$('#delete-cancel').onclick=()=>$('#delete-dialog').close();
$('#delete-confirm').onclick=async()=>{try{await commit({...state,entries:state.entries.filter(x=>x.id!==deleteId),attempts:state.attempts.filter(x=>x.entryId!==deleteId)});startDeck();render();$('#delete-dialog').close();notify('Entry deleted.')}catch(error){fail(error)}};
$('#load-demo').onclick=()=>loadDemo().catch(fail);$('#clear-demo').onclick=()=>clearDemo().catch(fail);
$('#load-model').onclick=loadModel;$('#cancel-model').onclick=cancelModel;
for(const id of ['settings-open','settings-top'])$('#'+id).onclick=()=>$('#settings-dialog').showModal();
document.querySelectorAll('.close-dialog').forEach(b=>b.onclick=()=>b.closest('dialog').close());
window.addEventListener('hashchange',()=>{if(location.hash==='#practice'&&!deck.length)startDeck();render();window.scrollTo(0,0)});
$('#date-label').textContent=new Date().toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric'});
try{await openDatabase()}catch(error){$('#storage-warning').hidden=false;$('#storage-warning').textContent='Notebook storage could not open. Please enable browser storage and reload. Your input cannot be saved yet.';console.error(error)}
startDeck();render();
if('serviceWorker' in navigator){navigator.serviceWorker.register('./sw.js').then(()=>navigator.serviceWorker.ready).then(()=>$('#offline-detail').textContent='The notebook shell is cached on this device. AI also needs its model downloaded and cached.').catch(()=>$('#offline-detail').textContent='Offline caching is unavailable in this browser. Use localhost or a secure connection.')}else $('#offline-detail').textContent='This browser does not support offline caching.';
function connectionLabel(){$('#offline-state').textContent=navigator.onLine?'Saved on this device':'Offline · Saved on this device'}window.addEventListener('online',connectionLabel);window.addEventListener('offline',connectionLabel);connectionLabel();
if(document.modelContext?.registerTool){const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});for(const tool of [{name:'read_barista_notebook',title:'Read barista notebook',description:'Read locally saved drink entries and practice counts.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input){if(input&&Object.keys(input).length)throw Error('This tool accepts no parameters.');return {entries:state.entries,progress:aggregate(state.entries,state.attempts)}}},{name:'start_barista_drink_entry',title:'Start a drink entry',description:'Open an unsaved drink entry form. Does not save or change the notebook.',inputSchema:{type:'object',properties:{drink:{type:'string',maxLength:80}},required:['drink'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||typeof input.drink!=='string'||!input.drink.trim()||input.drink.length>80||Object.keys(input).some(k=>k!=='drink'))throw Error('Provide a drink name between 1 and 80 characters.');goLog();$('#drink').value=input.drink;return {status:'unsaved_form_open',drink:input.drink}}}])Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(console.error)}
